    {
      "card_ids": ["C16"],
      "claim": "Mithramycin showed a low CSF:plasma ratio of 0.12 and little normal brain uptake, arguing against robust CNS access under intact barrier conditions.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Condition-matched human brain-tumor evidence supports meaningful CNS access under the glioma/brain-tumor condition, and additional positive brain-accumulation records support transfer. However, low structural similarity and several normal-barrier negative records limit confidence.",
